using System.Globalization;using System.Text.Json.Nodes;using Koz.Application.AdminCustomers;using Npgsql;
namespace Koz.Infrastructure.AdminCustomers;
public sealed class PostgresAdminCustomerRepository(NpgsqlDataSource data):IAdminCustomerRepository{
 const string CustomerFields="c.id,c.user_id,c.store_id,c.name,c.phone,c.email,c.subscription_status,CASE WHEN c.subscription_start_date IS NULL THEN NULL ELSE to_char(c.subscription_start_date::timestamp-interval '5 hours','YYYY-MM-DD\"T\"HH24:MI:SS.MS\"Z\"') END subscription_start_date,CASE WHEN c.subscription_end_date IS NULL THEN NULL ELSE to_char(c.subscription_end_date::timestamp-interval '5 hours','YYYY-MM-DD\"T\"HH24:MI:SS.MS\"Z\"') END subscription_end_date,c.subscription_auto_renew,to_char(c.created_at AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.MS\"Z\"') created_at,to_char(c.updated_at AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.MS\"Z\"') updated_at";
 public async Task<JsonObject> ListAsync(AdminCustomerQuery q,CancellationToken ct){var p=int.Parse(q.Page!);var l=int.Parse(q.Limit!);var where=Where(q,out var v);var total=await Scalar("SELECT COUNT(*)::int FROM customers c "+where,ct,v.ToArray());v.Add(l);v.Add((p-1)*l);return new(){["customers"]=await Array("SELECT COALESCE(json_agg(x ORDER BY created_at DESC),'[]')::text FROM (SELECT row_to_json(z) x,z.created_at FROM (SELECT "+CustomerFields+",COUNT(o.id)::int orders_count FROM customers c LEFT JOIN orders o ON o.customer_id=c.id "+where+" GROUP BY c.id)z ORDER BY created_at DESC LIMIT $"+(v.Count-1)+" OFFSET $"+v.Count+")a",ct,v.ToArray()),["pagination"]=new JsonObject{{"page",p},{"limit",l},{"total",int.Parse(total)}}};}
 public async Task<JsonObject> DetailAsync(string id,CancellationToken ct){var c=await One("SELECT row_to_json(x)::text FROM (SELECT "+CustomerFields+",COUNT(o.id)::int orders_count FROM customers c LEFT JOIN orders o ON o.customer_id=c.id WHERE c.id=$1 GROUP BY c.id)x",ct,Guid.Parse(id));if(c.Count==0)throw E("Customer was not found","customer_not_found");var a=await Array("SELECT COALESCE(json_agg(x ORDER BY created_at DESC),'[]')::text FROM (SELECT ca.*,sc.store_id,sc.address coverage_address,sc.entrance_count FROM customer_addresses ca JOIN store_coverage sc ON sc.id=ca.store_coverage_id WHERE ca.customer_id=$1)x",ct,Guid.Parse(id));var o=await Array("SELECT COALESCE(json_agg(x ORDER BY created_at DESC),'[]')::text FROM (SELECT id,order_number,subtotal,discount_total,delivery_fee,online_payment_amount,online_capture_amount,pos_terminal_topup,final_total,delivery_status,payment_status,fulfillment_window,delivery_date,created_at FROM orders WHERE customer_id=$1 ORDER BY created_at DESC LIMIT 10)x",ct,Guid.Parse(id));return new(){["customer"]=c,["addresses"]=a,["recent_orders"]=o};}
 public Task<JsonObject> SubscriptionsAsync(AdminSubscriptionQuery q,CancellationToken ct){var v=new List<object?>();var w="";if(!string.IsNullOrEmpty(q.StoreId)){v.Add(Guid.Parse(q.StoreId));w=" WHERE c.store_id=$1";}if(!string.IsNullOrEmpty(q.Status)){v.Add(q.Status);w+=(w==""?" WHERE ":" AND ")+"s.status=$"+v.Count;}return Wrap("subscriptions","SELECT COALESCE(json_agg(x ORDER BY created_at DESC),'[]')::text FROM (SELECT s.id,s.customer_id,s.amount::text amount,s.billing_period,s.status,to_char(s.expires_at AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.MS\"Z\"') expires_at,CASE WHEN s.next_billing_date IS NULL THEN NULL ELSE to_char(s.next_billing_date::timestamp-interval '5 hours','YYYY-MM-DD\"T\"HH24:MI:SS.MS\"Z\"') END next_billing_date,s.auto_renew,CASE WHEN s.cancelled_at IS NULL THEN NULL ELSE to_char(s.cancelled_at AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.MS\"Z\"') END cancelled_at,to_char(s.created_at AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.MS\"Z\"') created_at,to_char(s.updated_at AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.MS\"Z\"') updated_at,c.name customer_name,c.phone customer_phone,c.email customer_email,c.store_id FROM subscriptions s JOIN customers c ON c.id=s.customer_id"+w+")x",ct,v.ToArray());}
 public async Task<JsonObject> RenewAsync(string id,CancellationToken ct){await using var c=await data.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);try{await Customer(c,t,id,ct);var row=await One(c,t,"SELECT row_to_json(s)::text FROM (SELECT * FROM subscriptions WHERE customer_id=$1 ORDER BY expires_at DESC NULLS LAST,created_at DESC LIMIT 1 FOR UPDATE)s",ct,Guid.Parse(id));var now=DateTimeOffset.UtcNow;var baseDate=row.Count>0&&DateTimeOffset.Parse(row["expires_at"]!.GetValue<string>())>now?DateTimeOffset.Parse(row["expires_at"]!.GetValue<string>()).ToUniversalTime():now;var period=row.Count>0?row["billing_period"]!.GetValue<string>():"monthly";var exp=period=="yearly"?baseDate.AddYears(1):baseDate.AddMonths(1);var s=row.Count==0?await One(c,t,"INSERT INTO subscriptions(customer_id,amount,billing_period,status,expires_at,next_billing_date,auto_renew)VALUES($1,3900,'monthly','active',$2,$2::date,TRUE) RETURNING row_to_json(subscriptions)::text",ct,Guid.Parse(id),exp):await One(c,t,"UPDATE subscriptions SET status='active',expires_at=$2,next_billing_date=$2::date,auto_renew=TRUE,cancelled_at=NULL,updated_at=NOW() WHERE id=$1 RETURNING row_to_json(subscriptions)::text",ct,Guid.Parse(row["id"]!.GetValue<string>()),exp);await Exec(c,t,"UPDATE customers SET subscription_status='active',subscription_start_date=COALESCE(subscription_start_date,CURRENT_DATE),subscription_end_date=$2::date,subscription_auto_renew=TRUE,updated_at=NOW() WHERE id=$1",ct,Guid.Parse(id),exp);await t.CommitAsync(ct);return new(){["subscription"]=s};}catch{await t.RollbackAsync(CancellationToken.None);throw;}}
 public async Task<JsonObject> PauseAsync(string id,CancellationToken ct){await using var c=await data.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);try{await Customer(c,t,id,ct);var s=await One(c,t,"WITH x AS(SELECT id FROM subscriptions WHERE customer_id=$1 ORDER BY expires_at DESC NULLS LAST,created_at DESC LIMIT 1 FOR UPDATE) UPDATE subscriptions SET status='paused',auto_renew=FALSE,updated_at=NOW() WHERE id=(SELECT id FROM x) RETURNING row_to_json(subscriptions)::text",ct,Guid.Parse(id));if(s.Count==0)throw E("Active subscription was not found","subscription_not_found");await Exec(c,t,"UPDATE customers SET subscription_status='paused',subscription_auto_renew=FALSE,updated_at=NOW() WHERE id=$1",ct,Guid.Parse(id));await t.CommitAsync(ct);return new(){["subscription"]=s};}catch{await t.RollbackAsync(CancellationToken.None);throw;}}
 public async Task<JsonObject> CancelAsync(string id,bool immediate,CancellationToken ct){await using var c=await data.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);try{await Customer(c,t,id,ct);var sql=immediate?"WITH x AS(SELECT id FROM subscriptions WHERE customer_id=$1 AND status='active' ORDER BY expires_at DESC NULLS LAST,created_at DESC LIMIT 1 FOR UPDATE) UPDATE subscriptions SET status='cancelled',expires_at=NOW(),next_billing_date=NULL,auto_renew=FALSE,cancelled_at=NOW(),updated_at=NOW() WHERE id=(SELECT id FROM x) RETURNING row_to_json(subscriptions)::text":"WITH x AS(SELECT id FROM subscriptions WHERE customer_id=$1 AND status='active' ORDER BY expires_at DESC NULLS LAST,created_at DESC LIMIT 1 FOR UPDATE) UPDATE subscriptions SET auto_renew=FALSE,cancelled_at=NOW(),updated_at=NOW() WHERE id=(SELECT id FROM x) RETURNING row_to_json(subscriptions)::text";var s=await One(c,t,sql,ct,Guid.Parse(id));if(s.Count==0)throw E("Active subscription was not found","subscription_not_found");await Exec(c,t,immediate?"UPDATE customers SET subscription_status='cancelled',subscription_end_date=CURRENT_DATE,subscription_auto_renew=FALSE,updated_at=NOW() WHERE id=$1":"UPDATE customers SET subscription_auto_renew=FALSE,updated_at=NOW() WHERE id=$1",ct,Guid.Parse(id));await t.CommitAsync(ct);return new(){["subscription"]=s};}catch{await t.RollbackAsync(CancellationToken.None);throw;}}
 public Task<JsonObject> ConsentLogsAsync(CancellationToken ct)=>Wrap("audit_logs","SELECT COALESCE(json_agg(x ORDER BY consented_at DESC),'[]')::text FROM(SELECT u.id user_id,u.phone,u.name,consent.consent_type,uc.consented_at FROM user_consents uc JOIN users u ON u.id=uc.user_id CROSS JOIN LATERAL(VALUES('privacy_policy',uc.privacy_policy),('terms_of_service',uc.terms_of_service)) consent(consent_type,accepted) WHERE consent.accepted=TRUE)x",ct);
 public async Task<JsonObject> ExportAsync(AdminCustomerQuery q,CancellationToken ct){var w=Where(q,out var v);var rows=await Array("SELECT COALESCE(json_agg(x ORDER BY created_at DESC),'[]')::text FROM(SELECT c.id,c.store_id,c.name,c.phone,c.email,c.subscription_status,c.subscription_start_date,c.subscription_end_date,c.subscription_auto_renew,COUNT(o.id)::int orders_count,c.created_at FROM customers c LEFT JOIN orders o ON o.customer_id=c.id "+w+" GROUP BY c.id)x",ct,v.ToArray());return new(){["message"]="Customers export generated",["format"]="rows",["generated_at"]=DateTimeOffset.UtcNow.ToString("O"),["rows"]=rows};}
 static string Where(AdminCustomerQuery q,out List<object?> v){v=[];var a=new List<string>();if(!string.IsNullOrEmpty(q.StoreId)){v.Add(Guid.Parse(q.StoreId));a.Add("c.store_id=$"+v.Count);}if(!string.IsNullOrEmpty(q.SubscriptionStatus)){v.Add(q.SubscriptionStatus);a.Add("c.subscription_status=$"+v.Count);}if(!string.IsNullOrEmpty(q.Search)){v.Add("%"+q.Search+"%");a.Add("(c.phone ILIKE $"+v.Count+" OR c.name ILIKE $"+v.Count+")");}return a.Count==0?"":" WHERE "+string.Join(" AND ",a);}
 async Task Customer(NpgsqlConnection c,NpgsqlTransaction t,string id,CancellationToken ct){var x=await One(c,t,"SELECT row_to_json(customers)::text FROM customers WHERE id=$1",ct,Guid.Parse(id));if(x.Count==0)throw E("Customer was not found","customer_not_found");}
 async Task<JsonObject> Wrap(string k,string sql,CancellationToken ct,params object?[] x)=>new(){[k]=await Array(sql,ct,x)};
 async Task<string> Scalar(string s,CancellationToken ct,params object?[]x){await using var c=await data.OpenConnectionAsync(ct);await using var q=Cmd(c,null,s,x);return (await q.ExecuteScalarAsync(ct))!.ToString()!;}
 async Task<JsonArray> Array(string s,CancellationToken ct,params object?[]x){await using var c=await data.OpenConnectionAsync(ct);await using var q=Cmd(c,null,s,x);return JsonNode.Parse((await q.ExecuteScalarAsync(ct))!.ToString()!)!.AsArray();}
 async Task<JsonObject> One(string s,CancellationToken ct,params object?[]x){await using var c=await data.OpenConnectionAsync(ct);return await One(c,null,s,ct,x);}
 static async Task<JsonObject> One(NpgsqlConnection c,NpgsqlTransaction?t,string s,CancellationToken ct,params object?[]x){await using var q=Cmd(c,t,s,x);var z=await q.ExecuteScalarAsync(ct)as string;var o=z is null?new JsonObject():JsonNode.Parse(z)!.AsObject();if(o.ContainsKey("amount"))NormalizeSubscription(o);return o;}
 static void NormalizeSubscription(JsonObject o){if(o["amount"] is JsonValue a&&a.TryGetValue<decimal>(out var amount))o["amount"]=amount.ToString("0.00",CultureInfo.InvariantCulture);foreach(var key in new[]{"expires_at","cancelled_at","created_at","updated_at"})if(o[key]?.GetValue<string>() is string value&&DateTimeOffset.TryParse(value,out var time))o[key]=time.ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ss.fffZ",CultureInfo.InvariantCulture);if(o["next_billing_date"]?.GetValue<string>() is string date&&DateOnly.TryParse(date,out var day))o["next_billing_date"]=day.ToDateTime(TimeOnly.MinValue).AddHours(-5).ToString("yyyy-MM-ddTHH:mm:ss.fffZ",CultureInfo.InvariantCulture);}
 static async Task Exec(NpgsqlConnection c,NpgsqlTransaction t,string s,CancellationToken ct,params object?[]x){await using var q=Cmd(c,t,s,x);await q.ExecuteNonQueryAsync(ct);}static NpgsqlCommand Cmd(NpgsqlConnection c,NpgsqlTransaction?t,string s,params object?[]x){var q=new NpgsqlCommand(s,c,t);foreach(var z in x)q.Parameters.AddWithValue(z??DBNull.Value);return q;}static AdminCustomerContractException E(string m,string c)=>new(404,m,c);}
